using System;

Span<nint> signed = stackalloc nint[5];
Span<nuint> unsigned = stackalloc nuint[5];

for (int i = 0; i < signed.Length; i++)
{
    signed[i] = i * 10;
    unsigned[i] = (nuint)(i * 100);
}

Console.WriteLine($"nint size: {sizeof(nint)} bytes");
Console.WriteLine($"nuint size: {sizeof(nuint)} bytes");
Console.WriteLine();

Console.WriteLine("Span<nint>:");
foreach (var val in signed)
    Console.WriteLine($"  {val}");

Console.WriteLine("Span<nuint>:");
foreach (var val in unsigned)
    Console.WriteLine($"  {val}");

